const t={maxFlow:{intro:{t:0,b:{t:2,i:[{t:3}],s:"Tìm lưu lượng thể tích cao nhất (mm³/s) mà hotend của bạn có thể duy trì - bằng cách tăng dần lưu lượng trong khi theo dõi tải StallGuard của bộ đùn để bắt thời điểm bánh răng trượt. Hãy xem trước kế hoạch; bài kiểm tra trực tiếp sẽ gia nhiệt và đùn nhựa, vì vậy hãy chuẩn bị máy in trước khi chạy."}},help:{guide:{t:0,b:{t:2,i:[{t:3}],s:"Trợ giúp"}},guideTitle:{t:0,b:{t:2,i:[{t:3}],s:"Về Max-Flow"}},close:{t:0,b:{t:2,i:[{t:3}],s:"Đóng"}},howToRead:{t:0,b:{t:2,i:[{t:3}],s:"Cách dùng"}},steps:[{t:0,b:{t:2,i:[{t:3}],s:"Đặt nhiệt độ kiểm tra và đường kính filament (chọn một hotend để điền sẵn)."}},{t:0,b:{t:2,i:[{t:3}],s:"Xem trước kế hoạch - nó hiển thị từng bước lưu lượng và lượng filament được đẩy ra."}},{t:0,b:{t:2,i:[{t:3}],s:"Tích vào danh sách kiểm tra an toàn, rồi chạy bài kiểm tra trực tiếp (gia nhiệt + đùn)."}},{t:0,b:{t:2,i:[{t:3}],s:"Đọc lưu lượng duy trì tối đa và sao chép giá trị slicer được đề xuất."}}],topics:{howItWorks:{title:{t:0,b:{t:2,i:[{t:3}],s:"Cách bài kiểm tra hoạt động"}},body:{t:0,b:{t:2,i:[{t:3}],s:"Bộ đùn đẩy filament với lưu lượng thể tích tăng đều. Khi bánh răng kẹp filament tốt thì chỉ số tải StallGuard giữ ổn định; khi bắt đầu trượt thì các chỉ số nhảy lung tung. Lưu lượng cao nhất đạt được trước khi nhảy chính là lưu lượng tối đa duy trì được. Quá trình tăng dừng ngay khi phát hiện trượt, nên không có filament nào bị mài qua điểm trượt đầu tiên."}}},stallguard:{title:{t:0,b:{t:2,i:[{t:3}],s:"Phát hiện trượt bằng StallGuard"}},body:{t:0,b:{t:2,i:[{t:3}],s:"StallGuard là một tính năng của driver TMC báo cáo tải của động cơ. Bài kiểm tra này lấy mẫu nó nhiều lần mỗi bước lưu lượng và tìm sự tăng đột ngột về độ phân tán (IQR) hoặc biến thiên (CV) - dấu hiệu bánh răng mất độ bám. Ngưỡng đến từ một hồ sơ riêng cho từng driver. Lưu ý: trên bộ đùn TMC2209, cái này dùng đường SG4 thử nghiệm, nên hãy coi lần chạy đầu tiên là một lần hiệu chỉnh."}}},safety:{title:{t:0,b:{t:2,i:[{t:3}],s:"An toàn"}},body:{t:0,b:{t:2,i:[{t:3}],s:"Đây là bài kiểm tra nóng, có chuyển động, cố tình làm bộ đùn trượt. Hãy nạp filament, đảm bảo đầu phun thông thoáng (trên bàn in hoặc khu vực bỏ phế liệu), và ở gần đó. Lần chạy bị từ chối khi máy in đang in, và bộ gia nhiệt luôn được tắt khi kết thúc."}}},slicer:{title:{t:0,b:{t:2,i:[{t:3}],s:"Sử dụng kết quả"}},body:{t:0,b:{t:2,i:[{t:3}],s:'Đưa giá trị được đề xuất vào mục "max volumetric speed" trong slicer của bạn (cho mỗi filament). Con số thận trọng (80% mức tối đa đo được) là giới hạn an toàn cho dùng hằng ngày; con số cân bằng (90%) đẩy mạnh hơn một chút. Nhiệt độ hotend cao hơn thường nâng lưu lượng đạt được.'}}},glossary:{title:{t:0,b:{t:2,i:[{t:3}],s:"Thuật ngữ"}},body:{t:0,b:{static:"",t:2,i:[]}}}},glossary:{flow:{term:{t:0,b:{t:2,i:[{t:3}],s:"Lưu lượng thể tích"}},def:{t:0,b:{t:2,i:[{t:3}],s:"Lượng nhựa hotend làm chảy mỗi giây (mm³/s) - giới hạn tốc độ thực sự cho in nhanh."}}},stallguard:{term:{t:0,b:{t:2,i:[{t:3}],s:"StallGuard"}},def:{t:0,b:{t:2,i:[{t:3}],s:"Một tín hiệu của driver TMC báo cáo tải cơ học của động cơ, dùng ở đây để cảm nhận trượt bộ đùn."}}},slip:{term:{t:0,b:{t:2,i:[{t:3}],s:"Trượt"}},def:{t:0,b:{t:2,i:[{t:3}],s:"Khi bánh răng bộ đùn không còn kẹp filament đủ nhanh và bị trượt - trần lưu lượng."}}},meltzone:{term:{t:0,b:{t:2,i:[{t:3}],s:"Vùng nóng chảy"}},def:{t:0,b:{t:2,i:[{t:3}],s:"Phần được gia nhiệt của hotend; vùng nóng chảy dài hơn (ví dụ Volcano) duy trì lưu lượng cao hơn."}}}}},params:{title:{t:0,b:{t:2,i:[{t:3}],s:"Tham số kiểm tra"}},temperature:{t:0,b:{t:2,i:[{t:3}],s:"Nhiệt độ (°C)"}},filamentDiameter:{t:0,b:{t:2,i:[{t:3}],s:"Ø filament (mm)"}},hotend:{t:0,b:{t:2,i:[{t:3}],s:"Hotend (tùy chọn)"}},hotendNone:{t:0,b:{t:2,i:[{t:3}],s:"- không -"}},hotendHint:{t:0,b:{t:2,i:[{t:3,v:"Dự kiến ~"},{t:4,k:"flow"},{t:3,v:" mm³/s"}]}},startFlow:{t:0,b:{t:2,i:[{t:3}],s:"Lưu lượng đầu (mm³/s)"}},endFlow:{t:0,b:{t:2,i:[{t:3}],s:"Lưu lượng cuối (mm³/s)"}},stepFlow:{t:0,b:{t:2,i:[{t:3}],s:"Bước (mm³/s)"}},samples:{t:0,b:{t:2,i:[{t:3}],s:"Mẫu / bước"}},extrudePerStep:{t:0,b:{t:2,i:[{t:3}],s:"Đùn / bước (mm)"}},driver:{t:0,b:{t:2,i:[{t:3}],s:"Driver bộ đùn"}},driverDetected:{t:0,b:{t:2,i:[{t:3}],s:"phát hiện từ máy in"}},autoStealthchop:{t:0,b:{t:2,i:[{t:3}],s:"Tự động bật StealthChop cho bài kiểm tra"}},autoStealthchopHint:{t:0,b:{t:2,i:[{t:3}],s:"Chỉ TMC2209/2240: tạm thời ghi một stealthchop_threshold vào bộ đùn để StallGuard đọc được, rồi chú thích nó lại sau bài kiểm tra. Khôi phục printer.cfg; khởi động lại firmware cả hai chiều."}},method:{t:0,b:{t:2,i:[{t:3}],s:"Phương pháp phát hiện"}},methodHint:{t:0,b:{t:2,i:[{t:3}],s:"Auto dùng StallGuard, chuyển sang gia tốc kế trên toolhead (rung động) khi StallGuard không đọc được. Phương pháp gia tốc kế là thử nghiệm."}}},method:{auto:{t:0,b:{t:2,i:[{t:3}],s:"Auto"}},stallguard:{t:0,b:{t:2,i:[{t:3}],s:"StallGuard"}},accel:{t:0,b:{t:2,i:[{t:3}],s:"Gia tốc kế"}}},plan:{button:{t:0,b:{t:2,i:[{t:3}],s:"Xem trước kế hoạch"}},title:{t:0,b:{t:2,i:[{t:3}],s:"Quá trình tăng đã lập"}},stepCount:{t:0,b:{t:2,i:[{t:4,k:"count"},{t:3,v:" bước"}]}},totalExtrude:{t:0,b:{t:2,i:[{t:4,k:"mm"},{t:3,v:" mm filament"}]}},sgField:{t:0,b:{t:2,i:[{t:3,v:"Trường StallGuard: "},{t:4,k:"field"}]}},sgFieldUnknown:{t:0,b:{t:2,i:[{t:3}],s:"Không có trường StallGuard nào được biết cho driver này"}},flowHead:{t:0,b:{t:2,i:[{t:3}],s:"Lưu lượng (mm³/s)"}},feedrateHead:{t:0,b:{t:2,i:[{t:3}],s:"Tốc độ cấp (mm/min)"}},warning:{t:0,b:{t:2,i:[{t:3}],s:"Bài kiểm tra trực tiếp gia nhiệt hotend và đùn filament, cố tình đến mức trượt. Chỉ xem trước - chưa có gì chạy."}}},safety:{title:{t:0,b:{t:2,i:[{t:3}],s:"Trước khi chạy - danh sách kiểm tra an toàn"}},items:[{t:0,b:{t:2,i:[{t:3}],s:"Filament đã được nạp và cấp tự do."}},{t:0,b:{t:2,i:[{t:3}],s:"Đầu phun thông thoáng - trên bàn in hoặc thùng phế liệu, không lơ lửng trên các chi tiết."}},{t:0,b:{t:2,i:[{t:3}],s:"Tôi chấp nhận điều này sẽ cố tình mài/trượt một ít filament."}},{t:0,b:{t:2,i:[{t:3}],s:"Tôi sẽ ở cạnh máy in trong suốt bài kiểm tra."}}],ack:{t:0,b:{t:2,i:[{t:3}],s:"Tôi đã làm tất cả những điều trên và máy in đã sẵn sàng"}},note:{t:0,b:{t:2,i:[{t:3}],s:"Lần chạy bị từ chối khi đang in; bộ gia nhiệt được tắt tự động khi kết thúc."}}},run:{button:{t:0,b:{t:2,i:[{t:3}],s:"Chạy kiểm tra trực tiếp"}},running:{t:0,b:{t:2,i:[{t:3}],s:"Đang chạy… (gia nhiệt + đùn)"}},confirmTitle:{t:0,b:{t:2,i:[{t:3}],s:"Bắt đầu bài kiểm tra max-flow trực tiếp?"}},confirmBody:{t:0,b:{t:2,i:[{t:3,v:"Điều này gia nhiệt hotend đến "},{t:4,k:"temp"},{t:3,v:" °C và đùn tới "},{t:4,k:"mm"},{t:3,v:" mm filament, tăng dần cho đến khi bộ đùn trượt."}]}},confirm:{t:0,b:{t:2,i:[{t:3}],s:"Chạy ngay"}},cancel:{t:0,b:{t:2,i:[{t:3}],s:"Hủy"}},busy:{t:0,b:{t:2,i:[{t:3}],s:"Bị từ chối: máy in đang bận (đang in hoặc tạm dừng). Thử lại khi máy rảnh."}},error:{t:0,b:{t:2,i:[{t:3}],s:"Bài kiểm tra thất bại."}},noSg:{t:0,b:{t:2,i:[{t:3}],s:"Không đọc được mẫu StallGuard nào - kết quả trượt có thể không đáng tin. Trường SG trực tiếp của driver có lẽ cần điều chỉnh cho model này."}},progress:{t:0,b:{t:2,i:[{t:3,v:"Bước "},{t:4,k:"step"},{t:3,v:"/"},{t:4,k:"total"},{t:3,v:" - "},{t:4,k:"flow"},{t:3,v:" mm³/s"}]}},starting:{t:0,b:{t:2,i:[{t:3}],s:"Đang gia nhiệt / khởi động…"}},abort:{t:0,b:{t:2,i:[{t:3}],s:"Dừng lần chạy"}},cancelling:{t:0,b:{t:2,i:[{t:3}],s:"Đang dừng…"}},cancelled:{t:0,b:{t:2,i:[{t:3}],s:"Lần chạy đã dừng - bộ gia nhiệt đã được tắt."}},reattached:{t:0,b:{t:2,i:[{t:3}],s:"Đã kết nối lại: kết quả này hoàn tất khi trang đang vắng mặt."}},failed:{t:0,b:{t:2,i:[{t:3}],s:"Lần chạy max-flow thất bại."}},abortNote:{t:0,b:{t:2,i:[{t:3}],s:"Dừng luôn tắt bộ gia nhiệt."}},parkNote:{t:0,b:{t:2,i:[{t:3}],s:"Trước khi gia nhiệt, máy in home (nếu cần) và đưa đầu phun về giữa để có tầm nhìn rõ."}},phase:{enabling:{t:0,b:{t:2,i:[{t:3}],s:"Đang bật StealthChop…"}},homing:{t:0,b:{t:2,i:[{t:3}],s:"Đang home máy in…"}},centering:{t:0,b:{t:2,i:[{t:3}],s:"Đang đưa đầu phun về giữa…"}},heating:{t:0,b:{t:2,i:[{t:3}],s:"Đang gia nhiệt hotend…"}},checking:{t:0,b:{t:2,i:[{t:3}],s:"Đang kiểm tra tín hiệu StallGuard…"}},ramp:{t:0,b:{t:2,i:[{t:3}],s:"Đang tăng lưu lượng…"}},reverting:{t:0,b:{t:2,i:[{t:3}],s:"Đang khôi phục cấu hình…"}}},step:{home:{t:0,b:{t:2,i:[{t:3}],s:"Home"}},center:{t:0,b:{t:2,i:[{t:3}],s:"Giữa"}},heat:{t:0,b:{t:2,i:[{t:3}],s:"Gia nhiệt"}},check:{t:0,b:{t:2,i:[{t:3}],s:"Kiểm tra"}},ramp:{t:0,b:{t:2,i:[{t:3}],s:"Tăng"}}}},camera:{title:{t:0,b:{t:2,i:[{t:3}],s:"Camera trực tiếp"}},live:{t:0,b:{t:2,i:[{t:3}],s:"TRỰC TIẾP"}},error:{t:0,b:{t:2,i:[{t:3}],s:"Camera không khả dụng."}},willShow:{t:0,b:{t:2,i:[{t:3}],s:"Một khung camera trực tiếp sẽ hiển thị đầu phun trong bài kiểm tra."}},minimize:{t:0,b:{t:2,i:[{t:3}],s:"Thu nhỏ"}},maximize:{t:0,b:{t:2,i:[{t:3}],s:"Phóng to"}},enlarge:{t:0,b:{t:2,i:[{t:3}],s:"Mở rộng"}},shrink:{t:0,b:{t:2,i:[{t:3}],s:"Thu gọn"}}},result:{title:{t:0,b:{t:2,i:[{t:3}],s:"Kết quả"}},maxFlow:{t:0,b:{t:2,i:[{t:3}],s:"Lưu lượng duy trì tối đa"}},slipAt:{t:0,b:{t:2,i:[{t:3,v:"Phát hiện trượt tại "},{t:4,k:"flow"},{t:3,v:" mm³/s"}]}},noSlip:{t:0,b:{t:2,i:[{t:3}],s:"Không trượt cho tới mức lưu lượng được kiểm tra cao nhất"}},reason:{t:0,b:{t:2,i:[{t:3}],s:"Chi tiết"}},recommendTitle:{t:0,b:{t:2,i:[{t:3}],s:"Giá trị slicer được đề xuất (max volumetric speed)"}},conservative:{t:0,b:{t:2,i:[{t:3}],s:"Thận trọng (80%)"}},balanced:{t:0,b:{t:2,i:[{t:3}],s:"Cân bằng (90%)"}},units:{t:0,b:{t:2,i:[{t:3}],s:"mm³/s"}},fromBefore:{t:0,b:{t:2,i:[{t:3,v:"Đo trước đó ("},{t:4,k:"at"},{t:3,v:") - chạy lại để có số liệu mới."}]}},unreliableTitle:{t:0,b:{t:2,i:[{t:3}],s:"Không đáng tin - không có tín hiệu StallGuard"}},unmeasured:{t:0,b:{t:2,i:[{t:3}],s:"đã đạt, chưa xác nhận"}},via:{t:0,b:{t:2,i:[{t:3,v:"Đo qua "},{t:4,k:"method"}]}},accelExperimental:{t:0,b:{t:2,i:[{t:3}],s:"Đo bằng rung động (gia tốc kế) - thử nghiệm; coi con số như một hướng dẫn, không phải trần chính xác."}}},states:{loadingHotends:{t:0,b:{t:2,i:[{t:3}],s:"Đang tải hotend…"}}}}};export{t as default};
